import React, { useEffect, useMemo, useState } from 'react';
import { motion, animate, useReducedMotion } from 'motion/react';
import { LayoutDashboard, List, Target, Sparkles, LogOut, ShoppingCart, Utensils, Truck, ShoppingBag, FileText, HeartPulse, Film, TrendingUp, TrendingDown, Circle, ChevronRight, Wallet, CreditCard } from 'lucide-react';
import type { AppHandle } from '@app/kit/primitives';

type R = Record<string, unknown>;
type Icon = typeof Circle;
const CATS: Record<string, { label: string; color: string; Icon: Icon }> = {
  groceries: { label: 'Groceries', color: '#10B981', Icon: ShoppingCart },
  dining: { label: 'Dining', color: '#F59E0B', Icon: Utensils },
  transport: { label: 'Transport', color: '#8B5CF6', Icon: Truck },
  shopping: { label: 'Shopping', color: '#EC4899', Icon: ShoppingBag },
  bills: { label: 'Bills', color: '#2F6BFF', Icon: FileText },
  health: { label: 'Health', color: '#06B6D4', Icon: HeartPulse },
  fun: { label: 'Fun', color: '#F97316', Icon: Film },
  income: { label: 'Income', color: '#22C55E', Icon: TrendingUp },
  other: { label: 'Other', color: '#94A3B8', Icon: Circle },
};
const cat = (k: string) => CATS[k] || CATS.other;
const money = (n: number, d = 2) => (n < 0 ? '-' : '') + '$' + Math.abs(n).toLocaleString('en-US', { minimumFractionDigits: d, maximumFractionDigits: d });
const ymd = (d: Date) => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const sd = (s: string) => MONTHS[Number(s.slice(5, 7)) - 1] + ' ' + Number(s.slice(8, 10));
const CARD = 'rounded-3xl bg-white p-5 shadow-[0_1px_2px_rgba(15,23,42,0.04),0_14px_34px_-14px_rgba(15,23,42,0.14)]';
const TABS = [
  { k: 'dashboard', label: 'Home', route: '/dashboard', Icon: LayoutDashboard },
  { k: 'transactions', label: 'Activity', route: '/transactions', Icon: List },
  { k: 'budgets', label: 'Budgets', route: '/budgets', Icon: Target },
  { k: 'insights', label: 'Insights', route: '/insights', Icon: Sparkles },
];

function Shell({ app, active, children }: { app?: AppHandle; active: string; children: React.ReactNode }) {
  const name = String(app?.user.name || 'You');
  return (
    <div className='min-h-screen overflow-x-hidden bg-[#F4F6FB] text-slate-900 lg:flex'>
      <aside className='sticky top-0 hidden h-screen w-64 shrink-0 flex-col border-r border-slate-200/70 bg-white p-6 lg:flex'>
        <div className='flex items-center gap-2.5'>
          <div className='flex h-10 w-10 items-center justify-center rounded-xl bg-primary text-lg font-bold text-primary-foreground shadow-[0_8px_18px_-6px_rgba(47,107,255,0.7)]'>L</div>
          <span className='text-xl font-semibold tracking-tight'>Ledgerly</span>
        </div>
        <nav className='mt-10 flex flex-col gap-1'>
          {TABS.map((t) => (
            <button key={t.k} onClick={() => app?.navigate(t.route)} className={'relative flex items-center gap-3 rounded-2xl px-4 py-3 text-sm font-medium transition-colors ' + (active === t.k ? 'text-primary' : 'text-slate-500 hover:text-slate-900')}>
              {active === t.k && <motion.span layoutId='side-pill' className='absolute inset-0 rounded-2xl bg-primary/10' transition={{ type: 'spring', stiffness: 400, damping: 32 }} />}
              <t.Icon size={19} className='relative' />
              <span className='relative'>{t.label}</span>
            </button>
          ))}
        </nav>
        <div className='mt-auto flex items-center gap-3 rounded-2xl bg-slate-50 p-3'>
          <div className='flex h-10 w-10 items-center justify-center rounded-full bg-primary/15 text-sm font-bold text-primary'>{name[0]}</div>
          <div className='min-w-0 flex-1'>
            <div className='truncate text-sm font-semibold'>{name}</div>
            <div className='text-xs text-slate-400'>Member</div>
          </div>
          <button aria-label='Sign out' onClick={() => app?.auth.signOut()} className='rounded-lg p-2 text-slate-400 hover:bg-white hover:text-slate-700'><LogOut size={16} /></button>
        </div>
      </aside>
      <main className='min-w-0 flex-1 pb-28 lg:pb-12'>
        <div className='mx-auto w-full max-w-5xl px-4 pt-6 lg:px-10 lg:pt-10'>{children}</div>
      </main>
      <nav className='fixed inset-x-0 bottom-0 z-30 border-t border-slate-200/70 bg-white/85 px-2 pb-[max(env(safe-area-inset-bottom),8px)] pt-2 backdrop-blur-xl lg:hidden'>
        <div className='mx-auto flex max-w-md justify-around'>
          {TABS.map((t) => (
            <motion.button whileTap={{ scale: 0.9 }} key={t.k} onClick={() => app?.navigate(t.route)} className={'relative flex w-20 flex-col items-center gap-1 rounded-2xl py-1.5 text-[11px] font-medium ' + (active === t.k ? 'text-primary' : 'text-slate-400')}>
              <t.Icon size={22} strokeWidth={active === t.k ? 2.4 : 1.9} />
              {t.label}
              {active === t.k && <motion.span layoutId='tab-dot' className='absolute -top-2 h-1 w-8 rounded-full bg-primary' />}
            </motion.button>
          ))}
        </div>
      </nav>
    </div>
  );
}

function Rise({ i = 0, className = '', children }: { i?: number; className?: string; children: React.ReactNode }) {
  const reduce = useReducedMotion();
  return (
    <motion.div className={'min-w-0 ' + className} initial={reduce ? false : { opacity: 0, y: 18 }} animate={{ opacity: 1, y: 0 }} transition={{ type: 'spring', stiffness: 170, damping: 22, delay: reduce ? 0 : i * 0.07 }}>
      {children}
    </motion.div>
  );
}

function CountUp({ value, className }: { value: number; className?: string }) {
  const reduce = useReducedMotion();
  const [v, setV] = useState(reduce ? value : 0);
  useEffect(() => {
    if (reduce) { setV(value); return; }
    const c = animate(0, value, { duration: 1.2, ease: [0.22, 1, 0.36, 1], onUpdate: (x) => setV(x) });
    return () => c.stop();
  }, [value, reduce]);
  return <span className={className}>{money(v)}</span>;
}

export default function DashboardScreen({ app }: { app?: AppHandle }) {
  const reduce = useReducedMotion();
  const [now, setNow] = useState<Date | null>(null);
  const [hot, setHot] = useState<string | null>(null);
  useEffect(() => { setNow(new Date()); }, []);
  const txs = (app?.rows('transaction') || []) as R[];
  const accounts = (app?.rows('account') || []) as R[];
  const budgets = (app?.rows('budget') || []) as R[];
  const bills = (app?.rows('bill') || []) as R[];
  const me = (app?.rows('member') || [])[0] as R | undefined;
  const loading = !now || (!!app?.loading('transaction') && txs.length === 0);
  const ym = now ? ymd(now).slice(0, 7) : '';
  const first = String(app?.user.name || 'there').split(' ')[0];
  const hour = now ? now.getHours() : 12;
  const greet = hour < 12 ? 'Good morning' : hour < 18 ? 'Good afternoon' : 'Good evening';

  const d = useMemo(() => {
    const spend: Record<string, number> = {};
    let income = 0;
    let spent = 0;
    for (const t of txs) {
      if (String(t.date).slice(0, 7) !== ym) continue;
      const a = Number(t.amount);
      if (a < 0) { spend[String(t.category)] = (spend[String(t.category)] || 0) - a; spent -= a; } else income += a;
    }
    const list = Object.keys(spend).map((k) => ({ k, v: spend[k] })).sort((a, b) => b.v - a.v);
    return { spend, income, spent, list };
  }, [txs, ym]);

  const balance = accounts.reduce((s, a) => s + Number(a.balance || 0), 0);
  const net = d.income - d.spent;

  const upcoming = useMemo(() => {
    if (!now) return [];
    const t0 = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const dim = (y: number, m: number) => new Date(y, m + 1, 0).getDate();
    const paid = new Set(txs.filter((t) => t.bill_id && String(t.date).slice(0, 7) === ym).map((t) => String(t.bill_id)));
    return bills.filter((b) => b.active !== false).map((b) => {
      const day = Number(b.day_of_month);
      let dt = new Date(t0.getFullYear(), t0.getMonth(), Math.min(day, dim(t0.getFullYear(), t0.getMonth())));
      if (dt < t0) dt = new Date(t0.getFullYear(), t0.getMonth() + 1, Math.min(day, dim(t0.getFullYear(), t0.getMonth() + 1)));
      return { b, dt, days: Math.round((dt.getTime() - t0.getTime()) / 86400000), paid: paid.has(String(b.id)) && dt.getMonth() === t0.getMonth() };
    }).sort((a, b) => a.days - b.days).slice(0, 4);
  }, [bills, txs, now, ym]);

  const recent = [...txs].sort((a, b) => String(b.date).localeCompare(String(a.date))).slice(0, 5);
  const budgetRows = budgets.map((b) => {
    const lim = Number(b.monthly_limit);
    const sp = d.spend[String(b.category)] || 0;
    return { k: String(b.category), lim, sp, pct: lim ? sp / lim : 0 };
  }).sort((a, b) => b.pct - a.pct);

  const C = 2 * Math.PI * 46;
  let off = 0;
  const segs = d.list.map((s) => { const len = d.spent ? (s.v / d.spent) * C : 0; const seg = { ...s, len, off }; off += len; return seg; });
  const hotItem = d.list.find((s) => s.k === hot);

  const kindStyle: Record<string, string> = {
    checking: 'from-slate-900 to-slate-700',
    savings: 'from-primary to-[#1A3FB8]',
    credit: 'from-violet-500 to-fuchsia-500',
    cash: 'from-emerald-500 to-teal-500',
  };

  return (
    <Shell app={app} active='dashboard'>
      <Rise>
        <div className='mb-6 flex items-center justify-between'>
          <div>
            <div className='text-sm font-medium text-slate-400'>{greet}</div>
            <div className='text-3xl font-semibold tracking-tight lg:text-4xl'>{first}</div>
          </div>
          {me && me.photo ? (
            <img src={String(me.photo)} alt='' className='h-12 w-12 rounded-full bg-primary/15 object-cover ring-4 ring-white shadow-md' />
          ) : (
            <div className='flex h-12 w-12 items-center justify-center rounded-full bg-primary/15 font-bold text-primary'>{first[0]}</div>
          )}
        </div>
      </Rise>

      {loading ? (
        <div className='space-y-4'>
          <div className='h-52 animate-pulse rounded-3xl bg-slate-200/70' />
          <div className='grid grid-cols-2 gap-4'><div className='h-32 animate-pulse rounded-3xl bg-slate-200/70' /><div className='h-32 animate-pulse rounded-3xl bg-slate-200/70' /></div>
          <div className='h-64 animate-pulse rounded-3xl bg-slate-200/70' />
        </div>
      ) : (
        <div className='grid grid-cols-[minmax(0,1fr)] gap-5 lg:grid-cols-3'>
          <Rise i={1} className='lg:col-span-2 lg:row-start-1'>
            <div className='relative overflow-hidden rounded-[32px] bg-gradient-to-br from-primary via-primary to-[#1A3FB8] p-6 text-white shadow-[0_24px_50px_-18px_rgba(47,107,255,0.75)] lg:p-8'>
              <div className='pointer-events-none absolute -right-16 -top-20 h-64 w-64 rounded-full bg-white/10' />
              <div className='pointer-events-none absolute -bottom-24 right-24 h-56 w-56 rounded-full bg-[#7FA6FF]/25 blur-2xl' />
              <div className='relative text-sm font-medium text-white/70'>Total balance</div>
              <CountUp value={balance} className='relative mt-1 block text-5xl font-semibold tracking-tight tabular-nums lg:text-6xl' />
              <div className='relative mt-5 flex flex-wrap gap-2.5'>
                <div className='flex items-center gap-1.5 rounded-full bg-white/15 px-3.5 py-1.5 text-sm font-medium backdrop-blur'><TrendingUp size={15} /> In {money(d.income, 0)}</div>
                <div className='flex items-center gap-1.5 rounded-full bg-white/15 px-3.5 py-1.5 text-sm font-medium backdrop-blur'><TrendingDown size={15} /> Out {money(d.spent, 0)}</div>
                <div className='rounded-full bg-white px-3.5 py-1.5 text-sm font-semibold text-primary'>{net >= 0 ? '+' : '-'}{money(Math.abs(net), 0)} this month</div>
              </div>
            </div>
          </Rise>

          <Rise i={3} className='lg:col-span-2 lg:row-start-2'>
            <div className='mb-3 flex items-center justify-between'><div className='text-lg font-semibold'>Accounts</div><span className='text-xs text-slate-400'>{accounts.length} linked</span></div>
            <div className='-mx-4 flex snap-x gap-3 overflow-x-auto px-4 pb-3 lg:mx-0 lg:grid lg:grid-cols-2 lg:overflow-visible lg:px-0'>
              {accounts.map((a, i) => {
                const k = String(a.kind);
                const AI = k === 'credit' ? CreditCard : Wallet;
                return (
                  <motion.div key={String(a.id)} whileTap={{ scale: 0.97 }} whileHover={{ y: -3 }} initial={reduce ? false : { opacity: 0, x: 30 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.25 + i * 0.07, type: 'spring', stiffness: 180, damping: 22 }} className={'relative w-[220px] shrink-0 snap-start overflow-hidden rounded-3xl bg-gradient-to-br p-5 text-white shadow-lg lg:w-auto ' + (kindStyle[k] || kindStyle.checking)}>
                    <div className='pointer-events-none absolute -right-8 -top-8 h-28 w-28 rounded-full bg-white/10' />
                    <div className='relative flex items-center justify-between text-white/80'><AI size={18} /><span className='text-[11px] font-semibold uppercase tracking-wider'>{k}</span></div>
                    <div className='relative mt-6 text-xs text-white/70'>{String(a.name)}</div>
                    <div className='relative text-2xl font-semibold tabular-nums'>{money(Number(a.balance))}</div>
                  </motion.div>
                );
              })}
            </div>
          </Rise>

          <Rise i={2} className='lg:col-start-3 lg:row-span-2 lg:row-start-1'>
            <div className={CARD + ' h-full'}>
              <div className='flex items-center justify-between'><div className='text-lg font-semibold'>Spending</div><span className='text-xs text-slate-400'>This month</span></div>
              {d.list.length === 0 ? (
                <div className='py-10 text-center text-sm text-slate-400'>No spending yet this month.</div>
              ) : (
                <>
                  <div className='relative mx-auto mt-4 h-44 w-44'>
                    <svg viewBox='0 0 120 120' className='h-full w-full'>
                      <g transform='rotate(-90 60 60)'>
                        <circle cx='60' cy='60' r='46' fill='none' stroke='#EEF1F7' strokeWidth='12' />
                        {segs.map((s, i) => (
                          <motion.circle key={s.k} cx='60' cy='60' r='46' fill='none' stroke={cat(s.k).color} strokeWidth={hot === s.k ? 15 : 12} strokeDashoffset={-s.off} initial={reduce ? false : { strokeDasharray: '0 ' + C }} animate={{ strokeDasharray: Math.max(s.len - 2, 0.01) + ' ' + C }} transition={{ duration: 0.9, delay: 0.3 + i * 0.08, ease: [0.22, 1, 0.36, 1] }} style={{ opacity: hot && hot !== s.k ? 0.35 : 1, transition: 'opacity .2s, stroke-width .2s' }} />
                        ))}
                      </g>
                    </svg>
                    <div className='pointer-events-none absolute inset-0 flex flex-col items-center justify-center'>
                      <div className='text-[11px] font-medium uppercase tracking-wider text-slate-400'>{hotItem ? cat(hotItem.k).label : 'Spent'}</div>
                      <div className='text-2xl font-semibold tabular-nums'>{money(hotItem ? hotItem.v : d.spent, 0)}</div>
                    </div>
                  </div>
                  <div className='mt-4 space-y-1'>
                    {d.list.slice(0, 5).map((s) => (
                      <div key={s.k} onMouseEnter={() => setHot(s.k)} onMouseLeave={() => setHot(null)} onClick={() => setHot(hot === s.k ? null : s.k)} className='flex cursor-pointer items-center gap-2.5 rounded-xl px-2 py-1.5 text-sm hover:bg-slate-50'>
                        <span className='h-2.5 w-2.5 rounded-full' style={{ background: cat(s.k).color }} />
                        <span className='flex-1 text-slate-600'>{cat(s.k).label}</span>
                        <span className='font-medium tabular-nums'>{money(s.v, 0)}</span>
                      </div>
                    ))}
                  </div>
                </>
              )}
            </div>
          </Rise>

          <Rise i={4} className='lg:col-span-2 lg:row-start-3'>
            <div className={CARD}>
              <div className='mb-4 flex items-center justify-between'><div className='text-lg font-semibold'>Budgets</div><button onClick={() => app?.navigate('/budgets')} className='flex items-center text-sm font-medium text-primary'>Manage <ChevronRight size={16} /></button></div>
              {budgetRows.length === 0 && <div className='py-6 text-center text-sm text-slate-400'>No budgets yet. Set a monthly limit to track a category.</div>}
              <div className='space-y-5'>
                {budgetRows.map((b, i) => {
                  const over = b.sp > b.lim;
                  const c = cat(b.k);
                  return (
                    <div key={b.k}>
                      <div className='mb-1.5 flex items-center gap-3'>
                        <div className='flex h-9 w-9 items-center justify-center rounded-xl' style={{ background: c.color + '1F', color: c.color }}><c.Icon size={17} /></div>
                        <div className='flex-1 text-sm font-semibold'>{c.label}</div>
                        <div className={'text-sm tabular-nums ' + (over ? 'font-semibold text-red-500' : 'text-slate-500')}>{money(b.sp, 0)} <span className='text-slate-300'>/</span> {money(b.lim, 0)}</div>
                      </div>
                      <div className='h-2.5 overflow-hidden rounded-full bg-slate-100'>
                        <motion.div className='h-full rounded-full' style={{ background: over ? '#EF4444' : c.color }} initial={reduce ? false : { width: 0 }} animate={{ width: Math.min(b.pct, 1) * 100 + '%' }} transition={{ duration: 0.9, delay: 0.4 + i * 0.07, ease: [0.22, 1, 0.36, 1] }} />
                      </div>
                      <div className={'mt-1 text-xs ' + (over ? 'text-red-500' : 'text-slate-400')}>{over ? money(b.sp - b.lim, 0) + ' over budget' : money(b.lim - b.sp, 0) + ' left'}</div>
                    </div>
                  );
                })}
              </div>
            </div>
          </Rise>

          <Rise i={5} className='lg:col-start-3 lg:row-start-3 lg:self-start'>
            <div className={CARD}>
              <div className='mb-3 text-lg font-semibold'>Upcoming bills</div>
              {upcoming.length === 0 && <div className='py-6 text-center text-sm text-slate-400'>No recurring bills.</div>}
              <div className='space-y-3'>
                {upcoming.map((u) => (
                  <div key={String(u.b.id)} className='flex items-center gap-3'>
                    <div className='flex h-12 w-12 flex-col items-center justify-center rounded-2xl bg-slate-50 leading-none'>
                      <span className='text-[10px] font-semibold uppercase text-slate-400'>{MONTHS[u.dt.getMonth()]}</span>
                      <span className='mt-0.5 text-lg font-semibold'>{u.dt.getDate()}</span>
                    </div>
                    <div className='min-w-0 flex-1'>
                      <div className='truncate text-sm font-semibold'>{String(u.b.name)}</div>
                      <div className={'text-xs ' + (u.days === 0 && !u.paid ? 'font-medium text-amber-500' : 'text-slate-400')}>{u.paid ? 'Paid' : u.days === 0 ? 'Due today' : u.days === 1 ? 'Tomorrow' : 'In ' + u.days + ' days'}</div>
                    </div>
                    <div className='text-sm font-semibold tabular-nums'>{money(Number(u.b.amount))}</div>
                  </div>
                ))}
              </div>
            </div>
          </Rise>

          <Rise i={6} className='lg:col-span-3 lg:row-start-4'>
            <div className={CARD}>
              <div className='mb-2 flex items-center justify-between'><div className='text-lg font-semibold'>Recent activity</div><button onClick={() => app?.navigate('/transactions')} className='flex items-center text-sm font-medium text-primary'>See all <ChevronRight size={16} /></button></div>
              <div className='divide-y divide-slate-100'>
                {recent.map((t) => {
                  const c = cat(String(t.category));
                  const a = Number(t.amount);
                  return (
                    <div key={String(t.id)} className='flex items-center gap-3 py-3'>
                      <div className='flex h-10 w-10 items-center justify-center rounded-2xl' style={{ background: c.color + '1F', color: c.color }}><c.Icon size={18} /></div>
                      <div className='min-w-0 flex-1'><div className='truncate text-sm font-semibold'>{String(t.title)}</div><div className='text-xs text-slate-400'>{c.label} · {sd(String(t.date))}</div></div>
                      <div className={'text-sm font-semibold tabular-nums ' + (a > 0 ? 'text-emerald-600' : '')}>{a > 0 ? '+' : ''}{money(a)}</div>
                    </div>
                  );
                })}
              </div>
            </div>
          </Rise>
        </div>
      )}
    </Shell>
  );
}

import React, { useEffect, useMemo, useState } from 'react';
import { motion, AnimatePresence, animate, useAnimationControls, useDragControls, useReducedMotion } from 'motion/react';
import { LayoutDashboard, List, Target, Sparkles, LogOut, ShoppingCart, Utensils, Truck, ShoppingBag, FileText, HeartPulse, Film, TrendingUp, TrendingDown, Circle, Plus, Search, Trash2, X, Check, Inbox } from 'lucide-react';
import type { AppHandle } from '@app/kit/primitives';

type R = Record<string, unknown>;
type Icon = typeof Circle;
const CATS: Record<string, { label: string; color: string; Icon: Icon }> = {
  groceries: { label: 'Groceries', color: '#10B981', Icon: ShoppingCart },
  dining: { label: 'Dining', color: '#F59E0B', Icon: Utensils },
  transport: { label: 'Transport', color: '#8B5CF6', Icon: Truck },
  shopping: { label: 'Shopping', color: '#EC4899', Icon: ShoppingBag },
  bills: { label: 'Bills', color: '#2F6BFF', Icon: FileText },
  health: { label: 'Health', color: '#06B6D4', Icon: HeartPulse },
  fun: { label: 'Fun', color: '#F97316', Icon: Film },
  income: { label: 'Income', color: '#22C55E', Icon: TrendingUp },
  other: { label: 'Other', color: '#94A3B8', Icon: Circle },
};
const EXPENSE = ['groceries', 'dining', 'transport', 'shopping', 'bills', 'health', 'fun', 'other'];
const cat = (k: string) => CATS[k] || CATS.other;
const money = (n: number, d = 2) => (n < 0 ? '-' : '') + '$' + Math.abs(n).toLocaleString('en-US', { minimumFractionDigits: d, maximumFractionDigits: d });
const ymd = (d: Date) => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
const CARD = 'rounded-3xl bg-white p-5 shadow-[0_1px_2px_rgba(15,23,42,0.04),0_14px_34px_-14px_rgba(15,23,42,0.14)]';
const TABS = [
  { k: 'dashboard', label: 'Home', route: '/dashboard', Icon: LayoutDashboard },
  { k: 'transactions', label: 'Activity', route: '/transactions', Icon: List },
  { k: 'budgets', label: 'Budgets', route: '/budgets', Icon: Target },
  { k: 'insights', label: 'Insights', route: '/insights', Icon: Sparkles },
];

function Shell({ app, active, children }: { app?: AppHandle; active: string; children: React.ReactNode }) {
  const name = String(app?.user.name || 'You');
  return (
    <div className='min-h-screen overflow-x-hidden bg-[#F4F6FB] text-slate-900 lg:flex'>
      <aside className='sticky top-0 hidden h-screen w-64 shrink-0 flex-col border-r border-slate-200/70 bg-white p-6 lg:flex'>
        <div className='flex items-center gap-2.5'>
          <div className='flex h-10 w-10 items-center justify-center rounded-xl bg-primary text-lg font-bold text-primary-foreground shadow-[0_8px_18px_-6px_rgba(47,107,255,0.7)]'>L</div>
          <span className='text-xl font-semibold tracking-tight'>Ledgerly</span>
        </div>
        <nav className='mt-10 flex flex-col gap-1'>
          {TABS.map((t) => (
            <button key={t.k} onClick={() => app?.navigate(t.route)} className={'relative flex items-center gap-3 rounded-2xl px-4 py-3 text-sm font-medium transition-colors ' + (active === t.k ? 'text-primary' : 'text-slate-500 hover:text-slate-900')}>
              {active === t.k && <motion.span layoutId='side-pill' className='absolute inset-0 rounded-2xl bg-primary/10' transition={{ type: 'spring', stiffness: 400, damping: 32 }} />}
              <t.Icon size={19} className='relative' />
              <span className='relative'>{t.label}</span>
            </button>
          ))}
        </nav>
        <div className='mt-auto flex items-center gap-3 rounded-2xl bg-slate-50 p-3'>
          <div className='flex h-10 w-10 items-center justify-center rounded-full bg-primary/15 text-sm font-bold text-primary'>{name[0]}</div>
          <div className='min-w-0 flex-1'>
            <div className='truncate text-sm font-semibold'>{name}</div>
            <div className='text-xs text-slate-400'>Member</div>
          </div>
          <button aria-label='Sign out' onClick={() => app?.auth.signOut()} className='rounded-lg p-2 text-slate-400 hover:bg-white hover:text-slate-700'><LogOut size={16} /></button>
        </div>
      </aside>
      <main className='min-w-0 flex-1 pb-28 lg:pb-12'>
        <div className='mx-auto w-full max-w-5xl px-4 pt-6 lg:px-10 lg:pt-10'>{children}</div>
      </main>
      <nav className='fixed inset-x-0 bottom-0 z-30 border-t border-slate-200/70 bg-white/85 px-2 pb-[max(env(safe-area-inset-bottom),8px)] pt-2 backdrop-blur-xl lg:hidden'>
        <div className='mx-auto flex max-w-md justify-around'>
          {TABS.map((t) => (
            <motion.button whileTap={{ scale: 0.9 }} key={t.k} onClick={() => app?.navigate(t.route)} className={'relative flex w-20 flex-col items-center gap-1 rounded-2xl py-1.5 text-[11px] font-medium ' + (active === t.k ? 'text-primary' : 'text-slate-400')}>
              <t.Icon size={22} strokeWidth={active === t.k ? 2.4 : 1.9} />
              {t.label}
              {active === t.k && <motion.span layoutId='tab-dot' className='absolute -top-2 h-1 w-8 rounded-full bg-primary' />}
            </motion.button>
          ))}
        </div>
      </nav>
    </div>
  );
}

function Rise({ i = 0, className = '', children }: { i?: number; className?: string; children: React.ReactNode }) {
  const reduce = useReducedMotion();
  return (
    <motion.div className={'min-w-0 ' + className} initial={reduce ? false : { opacity: 0, y: 18 }} animate={{ opacity: 1, y: 0 }} transition={{ type: 'spring', stiffness: 170, damping: 22, delay: reduce ? 0 : i * 0.07 }}>
      {children}
    </motion.div>
  );
}

function TxSheet({ app, tx, accounts, today, onClose, onDone }: { app?: AppHandle; tx: R | null; accounts: R[]; today: string; onClose: () => void; onDone: (msg: string) => void }) {
  const controls = useDragControls();
  const a0 = tx ? Number(tx.amount) : 0;
  const [kind, setKind] = useState<'expense' | 'income'>(tx && a0 > 0 ? 'income' : 'expense');
  const [amount, setAmount] = useState(tx ? String(Math.abs(a0)) : '');
  const [title, setTitle] = useState(tx ? String(tx.title) : '');
  const [category, setCategory] = useState(tx && tx.category !== 'income' ? String(tx.category) : 'groceries');
  const [accountId, setAccountId] = useState(tx && tx.account_id ? String(tx.account_id) : '');
  const [date, setDate] = useState(tx ? String(tx.date).slice(0, 10) : today);
  const [note, setNote] = useState(tx && tx.note ? String(tx.note) : '');
  const [err, setErr] = useState('');
  const [shake, setShake] = useState(0);
  const [busy, setBusy] = useState(false);
  const field = 'w-full rounded-2xl border border-slate-200 bg-slate-50 px-4 py-3 text-[15px] outline-none transition focus:border-primary focus:bg-white focus:ring-4 focus:ring-primary/15';
  const lbl = 'mb-1.5 block text-xs font-semibold uppercase tracking-wide text-slate-500';

  const save = async () => {
    if (!app || busy) return;
    setErr('');
    setBusy(true);
    const n = parseFloat(amount.replace(/,/g, ''));
    const v = isFinite(n) ? n : 0;
    const values: R = {
      title: title.trim() || (kind === 'income' ? 'Income' : 'Expense'),
      amount: kind === 'expense' ? -Math.abs(v) : Math.abs(v),
      category: kind === 'income' ? 'income' : category,
      date,
      account_id: accountId || null,
      note: note.trim() || null,
    };
    try {
      if (tx) await app.update('transaction', String(tx.id), values);
      else await app.create('transaction', { ...values, member_id: app.me('member') });
      onDone(tx ? 'Transaction updated' : 'Transaction added');
    } catch (e) {
      setErr(e instanceof Error ? e.message : 'Could not save this transaction');
      setShake((s) => s + 1);
      setBusy(false);
    }
  };
  const del = async () => {
    if (!app || !tx) return;
    try { await app.remove('transaction', String(tx.id)); onDone('Transaction deleted'); } catch (e) { setErr('Could not delete'); }
  };

  return (
    <motion.div className='fixed inset-0 z-50 flex items-end justify-center bg-slate-900/40 backdrop-blur-[2px] lg:items-center' initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={onClose}>
      <motion.div
        onClick={(e) => e.stopPropagation()}
        drag='y'
        dragControls={controls}
        dragListener={false}
        dragConstraints={{ top: 0, bottom: 0 }}
        dragElastic={{ top: 0, bottom: 0.5 }}
        onDragEnd={(_, i) => { if (i.offset.y > 110) onClose(); }}
        initial={{ y: '100%' }}
        animate={{ y: 0 }}
        exit={{ y: '100%' }}
        transition={{ type: 'spring', stiffness: 320, damping: 34 }}
        className='max-h-[92vh] w-full max-w-lg overflow-y-auto rounded-t-[32px] bg-white px-6 pb-8 pt-3 shadow-2xl lg:rounded-[32px]'
      >
        <div onPointerDown={(e) => controls.start(e)} className='mx-auto mb-3 flex h-6 w-full cursor-grab touch-none justify-center lg:hidden'><div className='mt-1 h-1.5 w-12 rounded-full bg-slate-200' /></div>
        <div className='mb-4 flex items-center justify-between'>
          <div className='text-xl font-semibold'>{tx ? 'Edit transaction' : 'New transaction'}</div>
          <button aria-label='Close' onClick={onClose} className='rounded-full bg-slate-100 p-2 text-slate-500'><X size={16} /></button>
        </div>
        <div className='relative mb-5 grid grid-cols-2 rounded-2xl bg-slate-100 p-1'>
          {(['expense', 'income'] as const).map((k) => (
            <button key={k} onClick={() => setKind(k)} className={'relative z-10 rounded-xl py-2 text-sm font-semibold capitalize transition-colors ' + (kind === k ? 'text-slate-900' : 'text-slate-400')}>
              {kind === k && <motion.span layoutId='kind-pill' className='absolute inset-0 -z-10 rounded-xl bg-white shadow' transition={{ type: 'spring', stiffness: 420, damping: 34 }} />}
              {k}
            </button>
          ))}
        </div>
        <div className='mb-5 flex items-center justify-center gap-1'>
          <span className={'text-4xl font-semibold ' + (kind === 'expense' ? 'text-slate-300' : 'text-emerald-400')}>{kind === 'expense' ? '-$' : '+$'}</span>
          <input aria-label='Amount' inputMode='decimal' value={amount} onChange={(e) => setAmount(e.target.value)} placeholder='0.00' className='w-44 bg-transparent text-center text-5xl font-semibold tabular-nums outline-none placeholder:text-slate-200' />
        </div>
        <div className='space-y-4'>
          <div><label className={lbl}>Merchant</label><input className={field} value={title} onChange={(e) => setTitle(e.target.value)} placeholder='Where did it go?' /></div>
          {kind === 'expense' && (
            <div>
              <label className={lbl}>Category</label>
              <div className='grid grid-cols-4 gap-2'>
                {EXPENSE.map((k) => {
                  const c = cat(k);
                  const on = category === k;
                  return (
                    <motion.button whileTap={{ scale: 0.92 }} key={k} onClick={() => setCategory(k)} className={'flex flex-col items-center gap-1 rounded-2xl border-2 py-2.5 text-[11px] font-medium ' + (on ? 'bg-white' : 'border-transparent bg-slate-50 text-slate-500')} style={on ? { borderColor: c.color, color: c.color } : undefined}>
                      <c.Icon size={18} />
                      {c.label}
                    </motion.button>
                  );
                })}
              </div>
            </div>
          )}
          <div className='grid grid-cols-2 gap-3'>
            <div><label className={lbl}>Date</label><input type='date' className={field} value={date} onChange={(e) => setDate(e.target.value)} /></div>
            <div>
              <label className={lbl}>Account</label>
              <select className={field} value={accountId} onChange={(e) => setAccountId(e.target.value)}>
                <option value=''>None</option>
                {accounts.map((a) => <option key={String(a.id)} value={String(a.id)}>{String(a.name)}</option>)}
              </select>
            </div>
          </div>
          <div><label className={lbl}>Note</label><input className={field} value={note} onChange={(e) => setNote(e.target.value)} placeholder='Optional' /></div>
        </div>
        <AnimatePresence>
          {err && (
            <motion.div key={shake} initial={{ opacity: 0, x: -8 }} animate={{ opacity: 1, x: [0, -8, 8, -5, 5, 0] }} exit={{ opacity: 0 }} transition={{ duration: 0.4 }} className='mt-4 rounded-2xl bg-red-50 px-4 py-3 text-sm font-medium text-red-600'>{err}</motion.div>
          )}
        </AnimatePresence>
        <div className='mt-6 flex gap-3'>
          {tx && <motion.button whileTap={{ scale: 0.95 }} onClick={del} aria-label='Delete' className='flex h-14 w-14 items-center justify-center rounded-2xl bg-red-50 text-red-500'><Trash2 size={20} /></motion.button>}
          <motion.button whileTap={{ scale: 0.97 }} onClick={save} disabled={busy} className='flex h-14 flex-1 items-center justify-center gap-2 rounded-2xl bg-primary text-[15px] font-semibold text-primary-foreground shadow-[0_12px_26px_-10px_rgba(47,107,255,0.8)] disabled:opacity-60'>
            <Check size={18} /> {busy ? 'Saving' : tx ? 'Save changes' : 'Add transaction'}
          </motion.button>
        </div>
      </motion.div>
    </motion.div>
  );
}

function TxRow({ t, open, setOpen, onEdit, onDelete }: { t: R; open: boolean; setOpen: (v: boolean) => void; onEdit: () => void; onDelete: () => void }) {
  const ctl = useAnimationControls();
  const [peek, setPeek] = useState(false);
  const c = cat(String(t.category));
  const a = Number(t.amount);
  useEffect(() => { ctl.start({ x: open ? -96 : 0, transition: { type: 'spring', stiffness: 400, damping: 36 } }); }, [open, ctl]);
  return (
    <div className='relative overflow-hidden rounded-2xl'>
      <div className={'absolute inset-y-0 right-0 flex w-24 items-center justify-center bg-red-500 ' + (open || peek ? 'visible' : 'invisible')}>
        <button aria-label='Delete transaction' onClick={onDelete} className='flex h-full w-full items-center justify-center text-white'><Trash2 size={20} /></button>
      </div>
      <motion.div
        drag='x'
        dragConstraints={{ left: -96, right: 0 }}
        dragElastic={0.08}
        animate={ctl}
        onDragStart={() => setPeek(true)}
        onDragEnd={(_, i) => { const x = (open ? -96 : 0) + i.offset.x; const next = x < -48; setOpen(next); ctl.start({ x: next ? -96 : 0 }); if (!next) window.setTimeout(() => setPeek(false), 300); }}
        onTap={() => { if (open) setOpen(false); else onEdit(); }}
        whileTap={{ scale: 0.985 }}
        className='relative flex cursor-pointer items-center gap-3 bg-white px-4 py-3.5'
      >
        <div className='flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl' style={{ background: c.color + '1F', color: c.color }}><c.Icon size={19} /></div>
        <div className='min-w-0 flex-1'>
          <div className='truncate text-[15px] font-semibold'>{String(t.title)}</div>
          <div className='truncate text-xs text-slate-400'>{c.label}{t.note ? ' · ' + String(t.note) : ''}</div>
        </div>
        {t.alert === 'over' && <span className='rounded-full bg-red-50 px-2 py-0.5 text-[10px] font-semibold text-red-500'>Over budget</span>}
        <div className={'text-[15px] font-semibold tabular-nums ' + (a > 0 ? 'text-emerald-600' : 'text-slate-900')}>{a > 0 ? '+' : ''}{money(a)}</div>
      </motion.div>
    </div>
  );
}

export default function TransactionsScreen({ app }: { app?: AppHandle }) {
  const reduce = useReducedMotion();
  const [now, setNow] = useState<Date | null>(null);
  const [q, setQ] = useState('');
  const [filter, setFilter] = useState('all');
  const [sheet, setSheet] = useState<{ tx: R | null } | null>(null);
  const [openId, setOpenId] = useState<string | null>(null);
  const [toast, setToast] = useState('');
  useEffect(() => { setNow(new Date()); }, []);
  useEffect(() => { if (!toast) return; const id = window.setTimeout(() => setToast(''), 2600); return () => window.clearTimeout(id); }, [toast]);

  const txs = (app?.rows('transaction') || []) as R[];
  const accounts = (app?.rows('account') || []) as R[];
  const loading = !now || (!!app?.loading('transaction') && txs.length === 0);
  const today = now ? ymd(now) : '';
  const yest = now ? ymd(new Date(now.getTime() - 86400000)) : '';
  const ym = today.slice(0, 7);

  const filtered = useMemo(() => {
    const s = q.trim().toLowerCase();
    return txs.filter((t) => (filter === 'all' || String(t.category) === filter) && (!s || (String(t.title) + ' ' + cat(String(t.category)).label + ' ' + String(t.note || '')).toLowerCase().includes(s)))
      .sort((a, b) => String(b.date).localeCompare(String(a.date)));
  }, [txs, q, filter]);

  const groups = useMemo(() => {
    const m: { date: string; items: R[]; net: number }[] = [];
    for (const t of filtered) {
      const dt = String(t.date).slice(0, 10);
      let g = m[m.length - 1];
      if (!g || g.date !== dt) { g = { date: dt, items: [], net: 0 }; m.push(g); }
      g.items.push(t);
      g.net += Number(t.amount);
    }
    return m;
  }, [filtered]);

  const month = useMemo(() => {
    let inc = 0;
    let out = 0;
    const by: Record<string, number> = {};
    for (const t of txs) {
      if (String(t.date).slice(0, 7) !== ym) continue;
      const a = Number(t.amount);
      if (a > 0) inc += a; else { out -= a; by[String(t.category)] = (by[String(t.category)] || 0) - a; }
    }
    const top = Object.keys(by).map((k) => ({ k, v: by[k] })).sort((a, b) => b.v - a.v).slice(0, 5);
    return { inc, out, top };
  }, [txs, ym]);

  const dayLabel = (d: string) => d === today ? 'Today' : d === yest ? 'Yesterday' : new Date(d + 'T12:00:00').toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
  const usedCats = Array.from(new Set(txs.map((t) => String(t.category))));
  const closeSheet = () => setSheet(null);
  const del = async (t: R) => { try { await app?.remove('transaction', String(t.id)); setOpenId(null); setToast('Transaction deleted'); } catch (e) { setToast('Could not delete'); } };

  return (
    <Shell app={app} active='transactions'>
      <Rise>
        <div className='mb-5 flex items-end justify-between'>
          <div>
            <div className='text-sm font-medium text-slate-400'>All accounts</div>
            <div className='text-3xl font-semibold tracking-tight lg:text-4xl'>Activity</div>
          </div>
          <motion.button whileTap={{ scale: 0.95 }} whileHover={{ y: -1 }} onClick={() => setSheet({ tx: null })} className='hidden items-center gap-2 rounded-2xl bg-primary px-5 py-3 text-sm font-semibold text-primary-foreground shadow-[0_12px_24px_-10px_rgba(47,107,255,0.8)] lg:flex'><Plus size={18} /> Add transaction</motion.button>
        </div>
      </Rise>

      <div className='lg:grid lg:grid-cols-[minmax(0,1fr)_300px] lg:gap-8'>
        <div className='min-w-0'>
          <Rise i={1}>
            <div className='relative'>
              <Search size={18} className='pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-slate-400' />
              <input aria-label='Search transactions' value={q} onChange={(e) => setQ(e.target.value)} placeholder='Search merchants, categories, notes' className='w-full rounded-2xl border border-transparent bg-white py-3.5 pl-11 pr-4 text-[15px] shadow-[0_1px_2px_rgba(15,23,42,0.05)] outline-none transition focus:border-primary focus:ring-4 focus:ring-primary/15' />
            </div>
            <div className='-mx-4 mt-3 flex gap-2 overflow-x-auto px-4 pb-1 lg:mx-0 lg:px-0'>
              {['all', ...usedCats].map((k) => (
                <motion.button whileTap={{ scale: 0.94 }} key={k} onClick={() => setFilter(k)} className={'shrink-0 rounded-full px-4 py-2 text-sm font-medium transition-colors ' + (filter === k ? 'bg-slate-900 text-white' : 'bg-white text-slate-500')}>{k === 'all' ? 'All' : cat(k).label}</motion.button>
              ))}
            </div>
          </Rise>

          <div className='mt-3 grid grid-cols-2 gap-3 lg:hidden'>
            <div className={CARD + ' !p-4'}><div className='flex items-center gap-1.5 text-xs text-slate-400'><TrendingDown size={14} /> Spent</div><div className='mt-1 text-xl font-semibold tabular-nums'>{money(month.out, 0)}</div></div>
            <div className={CARD + ' !p-4'}><div className='flex items-center gap-1.5 text-xs text-slate-400'><TrendingUp size={14} /> Income</div><div className='mt-1 text-xl font-semibold tabular-nums text-emerald-600'>{money(month.inc, 0)}</div></div>
          </div>

          {loading ? (
            <div className='mt-6 space-y-3'>{[0, 1, 2, 3, 4].map((i) => <div key={i} className='h-[74px] animate-pulse rounded-2xl bg-slate-200/70' />)}</div>
          ) : groups.length === 0 ? (
            <Rise className='mt-10'>
              <div className='flex flex-col items-center rounded-3xl bg-white px-6 py-14 text-center'>
                <div className='flex h-16 w-16 items-center justify-center rounded-3xl bg-primary/10 text-primary'><Inbox size={28} /></div>
                <div className='mt-4 text-lg font-semibold'>{q || filter !== 'all' ? 'No matches' : 'No transactions yet'}</div>
                <div className='mt-1 max-w-xs text-sm text-slate-400'>{q || filter !== 'all' ? 'Try a different search or category.' : 'Add your first transaction to start tracking.'}</div>
                <button onClick={() => setSheet({ tx: null })} className='mt-5 rounded-2xl bg-primary px-5 py-3 text-sm font-semibold text-primary-foreground'>Add transaction</button>
              </div>
            </Rise>
          ) : (
            <div className='mt-6 space-y-6'>
              {groups.map((g, gi) => (
                <motion.div key={g.date} initial={reduce ? false : { opacity: 0, y: 16 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: Math.min(gi, 6) * 0.06, type: 'spring', stiffness: 180, damping: 24 }}>
                  <div className='mb-2 flex items-baseline justify-between px-1'>
                    <div className='text-sm font-semibold text-slate-700'>{dayLabel(g.date)}</div>
                    <div className='text-xs font-medium tabular-nums text-slate-400'>{g.net >= 0 ? '+' : '-'}{money(Math.abs(g.net))}</div>
                  </div>
                  <div className='space-y-2'>
                    <AnimatePresence initial={false}>
                      {g.items.map((t) => (
                        <motion.div key={String(t.id)} layout exit={{ opacity: 0, scale: 0.94, height: 0 }} className='rounded-2xl shadow-[0_1px_2px_rgba(15,23,42,0.04),0_8px_20px_-12px_rgba(15,23,42,0.12)]'>
                          <TxRow t={t} open={openId === String(t.id)} setOpen={(v) => setOpenId(v ? String(t.id) : null)} onEdit={() => setSheet({ tx: t })} onDelete={() => del(t)} />
                        </motion.div>
                      ))}
                    </AnimatePresence>
                  </div>
                </motion.div>
              ))}
            </div>
          )}
        </div>

        <aside className='hidden lg:block'>
          <div className='sticky top-10 space-y-5'>
            <Rise i={2}>
              <div className={CARD}>
                <div className='text-sm font-medium text-slate-400'>This month</div>
                <div className='mt-3 grid grid-cols-2 gap-3'>
                  <div><div className='text-xs text-slate-400'>Spent</div><div className='text-2xl font-semibold tabular-nums'>{money(month.out, 0)}</div></div>
                  <div><div className='text-xs text-slate-400'>Income</div><div className='text-2xl font-semibold tabular-nums text-emerald-600'>{money(month.inc, 0)}</div></div>
                </div>
                <div className='mt-5 space-y-3'>
                  {month.top.map((s, i) => (
                    <div key={s.k}>
                      <div className='mb-1 flex justify-between text-xs'><span className='font-medium text-slate-600'>{cat(s.k).label}</span><span className='tabular-nums text-slate-400'>{money(s.v, 0)}</span></div>
                      <div className='h-1.5 overflow-hidden rounded-full bg-slate-100'><motion.div className='h-full rounded-full' style={{ background: cat(s.k).color }} initial={{ width: 0 }} animate={{ width: (month.top[0] ? (s.v / month.top[0].v) * 100 : 0) + '%' }} transition={{ duration: 0.8, delay: 0.2 + i * 0.06 }} /></div>
                    </div>
                  ))}
                </div>
              </div>
            </Rise>
          </div>
        </aside>
      </div>

      <motion.button whileTap={{ scale: 0.9 }} initial={reduce ? false : { scale: 0 }} animate={{ scale: 1 }} transition={{ type: 'spring', stiffness: 300, damping: 18, delay: 0.4 }} aria-label='Add transaction' onClick={() => setSheet({ tx: null })} className='fixed bottom-24 right-5 z-20 flex h-14 w-14 items-center justify-center rounded-full bg-primary text-primary-foreground shadow-[0_14px_30px_-8px_rgba(47,107,255,0.85)] lg:hidden'><Plus size={26} /></motion.button>

      <AnimatePresence>
        {sheet && <TxSheet key='sheet' app={app} tx={sheet.tx} accounts={accounts} today={today} onClose={closeSheet} onDone={(m) => { closeSheet(); setOpenId(null); setToast(m); }} />}
      </AnimatePresence>

      <div className='pointer-events-none fixed inset-x-0 bottom-24 z-[60] flex justify-center lg:bottom-10'>
        <AnimatePresence>
          {toast && (
            <motion.div key={toast} initial={{ opacity: 0, y: 20, scale: 0.95 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, y: 10 }} className='flex items-center gap-2 rounded-full bg-slate-900 px-5 py-3 text-sm font-medium text-white shadow-2xl'><Check size={16} className='text-emerald-400' /> {toast}</motion.div>
          )}
        </AnimatePresence>
      </div>
    </Shell>
  );
}

import React, { useEffect, useMemo, useState } from 'react';
import { motion, AnimatePresence, useDragControls, useReducedMotion } from 'motion/react';
import { LayoutDashboard, List, Target, Sparkles, LogOut, ShoppingCart, Utensils, Truck, ShoppingBag, FileText, HeartPulse, Film, TrendingUp, Circle, Plus, Trash2, X, Check, CalendarDays } from 'lucide-react';
