}

function ErrBox({ err }: { err: string }) {
  return (
    <AnimatePresence>
      {err && <motion.div initial={{ opacity: 0, y: -6 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} className='mt-4 rounded-2xl bg-red-50 px-4 py-3 text-sm font-medium text-red-600'>{err}</motion.div>}
    </AnimatePresence>
  );
}

function BudgetSheet({ app, row, used, onClose, onDone }: { app?: AppHandle; row: R | null; used: string[]; onClose: () => void; onDone: (m: string) => void }) {
  const free = EXPENSE.filter((k) => !used.includes(k));
  const [category, setCategory] = useState(row ? String(row.category) : free[0] || 'other');
  const [limit, setLimit] = useState(row ? String(row.monthly_limit) : '');
  const [err, setErr] = useState('');
  const [busy, setBusy] = useState(false);
  const save = async () => {
    if (!app || busy) return;
    setBusy(true);
    setErr('');
    const v = parseFloat(limit.replace(/,/g, ''));
    const values: R = { category, monthly_limit: isFinite(v) ? v : 0 };
    try {
      if (row) await app.update('budget', String(row.id), values);
      else await app.create('budget', { ...values, member_id: app.me('member') });
      onDone(row ? 'Budget updated' : 'Budget created');
    } catch (e) { setErr(e instanceof Error ? e.message : 'Could not save'); setBusy(false); }
  };
  const del = async () => { if (!app || !row) return; try { await app.remove('budget', String(row.id)); onDone('Budget removed'); } catch (e) { setErr('Could not delete'); } };
  return (
    <Sheet title={row ? 'Edit budget' : 'New budget'} onClose={onClose}>
      {!row && <div className='mb-5'><label className={LBL}>Category</label><CatPicker value={category} onChange={setCategory} options={free} /></div>}
      {row && <div className='mb-5 flex items-center gap-3'><div className='flex h-12 w-12 items-center justify-center rounded-2xl' style={{ background: cat(category).color + '1F', color: cat(category).color }}>{React.createElement(cat(category).Icon, { size: 22 })}</div><div className='text-lg font-semibold'>{cat(category).label}</div></div>}
      <label className={LBL}>Monthly limit</label>
      <div className='mb-3 flex items-center justify-center gap-1 rounded-2xl bg-slate-50 py-4'>
        <span className='text-3xl font-semibold text-slate-300'>$</span>
        <input aria-label='Monthly limit' inputMode='decimal' value={limit} onChange={(e) => setLimit(e.target.value)} placeholder='0' className='w-40 bg-transparent text-center text-5xl font-semibold tabular-nums outline-none placeholder:text-slate-200' />
      </div>
      <div className='flex gap-2'>{[100, 250, 500, 1000].map((v) => <motion.button whileTap={{ scale: 0.93 }} key={v} onClick={() => setLimit(String(v))} className='flex-1 rounded-xl bg-slate-100 py-2 text-sm font-medium text-slate-600'>${v}</motion.button>)}</div>
      <ErrBox err={err} />
      <SaveBar busy={busy} onSave={save} onDelete={row ? del : undefined} label={row ? 'Save budget' : 'Create budget'} />
    </Sheet>
  );
}

function BillSheet({ app, row, onClose, onDone }: { app?: AppHandle; row: R | null; onClose: () => void; onDone: (m: string) => void }) {
  const [name, setName] = useState(row ? String(row.name) : '');
  const [amount, setAmount] = useState(row ? String(row.amount) : '');
  const [day, setDay] = useState(row ? String(row.day_of_month) : '1');
  const [category, setCategory] = useState(row ? String(row.category) : 'bills');
  const [active, setActive] = useState(row ? row.active !== false : true);
  const [err, setErr] = useState('');
  const [busy, setBusy] = useState(false);
  const save = async () => {
    if (!app || busy) return;
    setBusy(true);
    setErr('');
    const a = parseFloat(amount.replace(/,/g, ''));
    const values: R = { name: name.trim() || 'Bill', amount: isFinite(a) ? Math.abs(a) : 0, day_of_month: parseInt(day, 10) || 0, category, active };
    try {
      if (row) await app.update('bill', String(row.id), values);
      else await app.create('bill', { ...values, member_id: app.me('member') });
      onDone(row ? 'Bill updated' : 'Bill added');
    } catch (e) { setErr(e instanceof Error ? e.message : 'Could not save'); setBusy(false); }
  };
  const del = async () => { if (!app || !row) return; try { await app.remove('bill', String(row.id)); onDone('Bill removed'); } catch (e) { setErr('Could not delete'); } };
  return (
    <Sheet title={row ? 'Edit bill' : 'New recurring bill'} onClose={onClose}>
      <div className='space-y-4'>
        <div><label className={LBL}>Name</label><input className={FIELD} value={name} onChange={(e) => setName(e.target.value)} placeholder='Rent, Netflix, Gym' /></div>
        <div className='grid grid-cols-2 gap-3'>
          <div><label className={LBL}>Amount</label><input inputMode='decimal' className={FIELD} value={amount} onChange={(e) => setAmount(e.target.value)} placeholder='0.00' /></div>
          <div><label className={LBL}>Day of month</label><input type='number' min={1} max={31} className={FIELD} value={day} onChange={(e) => setDay(e.target.value)} /></div>
        </div>
        <div><label className={LBL}>Category</label><CatPicker value={category} onChange={setCategory} options={EXPENSE} /></div>
        <button onClick={() => setActive(!active)} className='flex w-full items-center justify-between rounded-2xl bg-slate-50 px-4 py-3'>
          <span className='text-sm font-medium text-slate-700'>Create a transaction automatically each month</span>
          <span className={'flex h-7 w-12 items-center rounded-full p-1 transition-colors ' + (active ? 'bg-primary' : 'bg-slate-300')}><motion.span layout transition={{ type: 'spring', stiffness: 500, damping: 32 }} className='h-5 w-5 rounded-full bg-white shadow' style={{ marginLeft: active ? 'auto' : 0 }} /></span>
        </button>
      </div>
      <ErrBox err={err} />
      <SaveBar busy={busy} onSave={save} onDelete={row ? del : undefined} label={row ? 'Save bill' : 'Add bill'} />
    </Sheet>
  );
}

export default function BudgetsScreen({ app }: { app?: AppHandle }) {
  const reduce = useReducedMotion();
  const [now, setNow] = useState<Date | null>(null);
  const [tab, setTab] = useState<'budgets' | 'bills'>('budgets');
  const [sheet, setSheet] = useState<{ kind: 'budget' | 'bill'; row: R | null } | null>(null);
  const [toast, setToast] = useState('');
  useEffect(() => { setNow(new Date()); }, []);
  useEffect(() => { if (!toast) return; const id = window.setTimeout(() => setToast(''), 2600); return () => window.clearTimeout(id); }, [toast]);

  const txs = (app?.rows('transaction') || []) as R[];
  const budgets = (app?.rows('budget') || []) as R[];
  const bills = (app?.rows('bill') || []) as R[];
  const loading = !now || (!!app?.loading('budget') && budgets.length === 0);
  const ym = now ? ymd(now).slice(0, 7) : '';

  const spend = useMemo(() => {
    const s: Record<string, number> = {};
    for (const t of txs) { if (String(t.date).slice(0, 7) === ym && Number(t.amount) < 0) s[String(t.category)] = (s[String(t.category)] || 0) - Number(t.amount); }
    return s;
  }, [txs, ym]);

  const rows = budgets.map((b) => { const lim = Number(b.monthly_limit); const sp = spend[String(b.category)] || 0; return { b, k: String(b.category), lim, sp, pct: lim ? sp / lim : 0 }; }).sort((a, b) => b.pct - a.pct);
  const totalLim = rows.reduce((s, r) => s + r.lim, 0);
  const totalSp = rows.reduce((s, r) => s + r.sp, 0);
  const overCount = rows.filter((r) => r.sp > r.lim).length;
  const used = budgets.map((b) => String(b.category));
  const free = EXPENSE.filter((k) => !used.includes(k));
  const activeBills = bills.filter((b) => b.active !== false);
  const billTotal = activeBills.reduce((s, b) => s + Number(b.amount), 0);
  const sortedBills = [...bills].sort((a, b) => Number(a.day_of_month) - Number(b.day_of_month));
  const close = () => setSheet(null);
  const ordinal = (n: number) => n + (n % 10 === 1 && n !== 11 ? 'st' : n % 10 === 2 && n !== 12 ? 'nd' : n % 10 === 3 && n !== 13 ? 'rd' : 'th');

  return (
    <Shell app={app} active='budgets'>
      <Rise>
        <div className='mb-5 flex items-end justify-between'>
          <div>
            <div className='text-sm font-medium text-slate-400'>Plan your month</div>
            <div className='text-3xl font-semibold tracking-tight lg:text-4xl'>Budgets</div>
          </div>
          <motion.button whileTap={{ scale: 0.95 }} whileHover={{ y: -1 }} onClick={() => setSheet(tab === 'budgets' ? (free.length ? { kind: 'budget', row: null } : null) : { kind: 'bill', row: null })} className='hidden items-center gap-2 rounded-2xl bg-primary px-5 py-3 text-sm font-semibold text-primary-foreground shadow-[0_12px_24px_-10px_rgba(47,107,255,0.8)] lg:flex'><Plus size={18} /> {tab === 'budgets' ? 'New budget' : 'New bill'}</motion.button>
        </div>
        <div className='relative mb-5 grid max-w-sm grid-cols-2 rounded-2xl bg-slate-200/60 p-1'>
          {([['budgets', 'Budgets'], ['bills', 'Recurring bills']] as const).map(([k, l]) => (
            <button key={k} onClick={() => setTab(k)} className={'relative z-10 rounded-xl py-2.5 text-sm font-semibold transition-colors ' + (tab === k ? 'text-slate-900' : 'text-slate-500')}>
              {tab === k && <motion.span layoutId='bt-pill' className='absolute inset-0 -z-10 rounded-xl bg-white shadow' transition={{ type: 'spring', stiffness: 420, damping: 34 }} />}
              {l}
            </button>
          ))}
        </div>
      </Rise>

      {loading ? (
        <div className='space-y-3'><div className='h-36 animate-pulse rounded-3xl bg-slate-200/70' />{[0, 1, 2].map((i) => <div key={i} className='h-24 animate-pulse rounded-3xl bg-slate-200/70' />)}</div>
      ) : (
        <AnimatePresence mode='wait' initial={false}>
          {tab === 'budgets' ? (
            <motion.div key='b' initial={{ opacity: 0, x: -16 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: 16 }} transition={{ duration: 0.2 }}>
              <div className='relative mb-5 overflow-hidden rounded-[32px] bg-gradient-to-br from-primary to-[#1A3FB8] p-6 text-white shadow-[0_24px_50px_-18px_rgba(47,107,255,0.75)]'>
                <div className='pointer-events-none absolute -right-12 -top-16 h-52 w-52 rounded-full bg-white/10' />
                <div className='relative text-sm font-medium text-white/70'>{totalLim - totalSp >= 0 ? 'Left to spend' : 'Over by'}</div>
                <div className='relative text-5xl font-semibold tabular-nums tracking-tight'>{money(Math.abs(totalLim - totalSp), 0)}</div>
                <div className='relative mt-4 h-2.5 overflow-hidden rounded-full bg-white/20'>
                  <motion.div className='h-full rounded-full bg-white' initial={reduce ? false : { width: 0 }} animate={{ width: Math.min(totalLim ? totalSp / totalLim : 0, 1) * 100 + '%' }} transition={{ duration: 1, ease: [0.22, 1, 0.36, 1] }} />
                </div>
                <div className='relative mt-3 flex justify-between text-sm text-white/80'><span>{money(totalSp, 0)} spent of {money(totalLim, 0)}</span><span>{overCount > 0 ? overCount + ' over' : 'On track'}</span></div>
              </div>
              <div className='grid gap-3 lg:grid-cols-2'>
                {rows.map((r, i) => {
                  const c = cat(r.k);
                  const over = r.sp > r.lim;
                  return (
                    <motion.button key={String(r.b.id)} initial={reduce ? false : { opacity: 0, y: 16 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 + i * 0.05, type: 'spring', stiffness: 180, damping: 22 }} whileTap={{ scale: 0.97 }} whileHover={{ y: -2 }} onClick={() => setSheet({ kind: 'budget', row: r.b })} className={CARD + ' w-full text-left'}>
                      <div className='flex items-center gap-3'>
                        <div className='flex h-11 w-11 items-center justify-center rounded-2xl' style={{ background: c.color + '1F', color: c.color }}><c.Icon size={20} /></div>
                        <div className='min-w-0 flex-1'><div className='font-semibold'>{c.label}</div><div className={'text-xs ' + (over ? 'font-medium text-red-500' : 'text-slate-400')}>{over ? money(r.sp - r.lim, 0) + ' over' : money(r.lim - r.sp, 0) + ' left'}</div></div>
                        <div className='text-right'><div className={'text-lg font-semibold tabular-nums ' + (over ? 'text-red-500' : '')}>{money(r.sp, 0)}</div><div className='text-xs text-slate-400'>of {money(r.lim, 0)}</div></div>
                      </div>
                      <div className='mt-3.5 h-2.5 overflow-hidden rounded-full bg-slate-100'>
                        <motion.div className='h-full rounded-full' style={{ background: over ? '#EF4444' : c.color }} initial={reduce ? false : { width: 0 }} animate={{ width: Math.min(r.pct, 1) * 100 + '%' }} transition={{ duration: 0.9, delay: 0.2 + i * 0.05, ease: [0.22, 1, 0.36, 1] }} />
                      </div>
                    </motion.button>
                  );
                })}
              </div>
              {rows.length === 0 && <div className='rounded-3xl bg-white px-6 py-12 text-center text-sm text-slate-400'>No budgets yet. Create one to start tracking a category.</div>}
              {free.length > 0 && (
                <motion.button whileTap={{ scale: 0.98 }} onClick={() => setSheet({ kind: 'budget', row: null })} className='mt-4 flex w-full items-center justify-center gap-2 rounded-3xl border-2 border-dashed border-slate-300 py-5 text-sm font-semibold text-slate-500 hover:border-primary hover:text-primary'><Plus size={18} /> Add a budget ({free.length} categories left)</motion.button>
              )}
            </motion.div>
          ) : (
            <motion.div key='r' initial={{ opacity: 0, x: 16 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -16 }} transition={{ duration: 0.2 }}>
              <div className={CARD + ' mb-5 flex items-center justify-between'}>
