                      <div className='flex h-12 w-12 flex-col items-center justify-center rounded-2xl leading-none' style={{ background: c.color + '1F', color: c.color }}><span className='text-[9px] font-bold uppercase opacity-70'>Day</span><span className='text-lg font-semibold'>{String(b.day_of_month)}</span></div>
                      <div className='min-w-0 flex-1'><div className='truncate font-semibold'>{String(b.name)}</div><div className='text-xs text-slate-400'>{ordinal(Number(b.day_of_month))} of every month{on ? '' : ' · paused'}</div></div>
                      <div className='text-lg font-semibold tabular-nums'>{money(Number(b.amount))}</div>
                    </motion.button>
                  );
                })}
              </div>
              {bills.length === 0 && <div className='rounded-3xl bg-white px-6 py-12 text-center text-sm text-slate-400'>No recurring bills yet.</div>}
              <motion.button whileTap={{ scale: 0.98 }} onClick={() => setSheet({ kind: 'bill', row: null })} className='mt-4 flex w-full items-center justify-center gap-2 rounded-3xl border-2 border-dashed border-slate-300 py-5 text-sm font-semibold text-slate-500 hover:border-primary hover:text-primary'><Plus size={18} /> Add a recurring bill</motion.button>
            </motion.div>
          )}
        </AnimatePresence>
      )}

      <AnimatePresence>
        {sheet && sheet.kind === 'budget' && <BudgetSheet key='bs' app={app} row={sheet.row} used={used} onClose={close} onDone={(m) => { close(); setToast(m); }} />}
        {sheet && sheet.kind === 'bill' && <BillSheet key='ls' app={app} row={sheet.row} onClose={close} onDone={(m) => { close(); setToast(m); }} />}
      </AnimatePresence>
      <div className='pointer-events-none fixed inset-x-0 bottom-24 z-[60] flex justify-center lg:bottom-10'>
        <AnimatePresence>
          {toast && <motion.div key={toast} initial={{ opacity: 0, y: 20, scale: 0.95 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, y: 10 }} className='flex items-center gap-2 rounded-full bg-slate-900 px-5 py-3 text-sm font-medium text-white shadow-2xl'><Check size={16} className='text-emerald-400' /> {toast}</motion.div>}
        </AnimatePresence>
      </div>
    </Shell>
  );
}

import React, { useEffect, useMemo, useState } from 'react';
import { motion, AnimatePresence, useReducedMotion } from 'motion/react';
import { LayoutDashboard, List, Target, Sparkles, LogOut, ShoppingCart, Utensils, Truck, ShoppingBag, FileText, HeartPulse, Film, TrendingUp, TrendingDown, Circle, RefreshCw } from 'lucide-react';
