  income: { label: 'Income', color: '#22C55E', Icon: TrendingUp },
  other: { label: 'Other', color: '#94A3B8', Icon: Circle },
};
const cat = (k: string) => CATS[k] || CATS.other;
const money = (n: number, d = 2) => (n < 0 ? '-' : '') + '$' + Math.abs(n).toLocaleString('en-US', { minimumFractionDigits: d, maximumFractionDigits: d });
const ymd = (d: Date) => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const CARD = 'rounded-3xl bg-white p-5 shadow-[0_1px_2px_rgba(15,23,42,0.04),0_14px_34px_-14px_rgba(15,23,42,0.14)]';
