function Rise({ i = 0, className = '', children }: { i?: number; className?: string; children: React.ReactNode }) {
  const reduce = useReducedMotion();
  return (
    <motion.div className={'min-w-0 ' + className} initial={reduce ? false : { opacity: 0, y: 18 }} animate={{ opacity: 1, y: 0 }} transition={{ type: 'spring', stiffness: 170, damping: 22, delay: reduce ? 0 : i * 0.07 }}>
      {children}
    </motion.div>
  );
}

export default function InsightsScreen({ app }: { app?: AppHandle }) {
  const reduce = useReducedMotion();
  const [now, setNow] = useState<Date | null>(null);
  const [bullets, setBullets] = useState<string[]>([]);
  const [state, setState] = useState<'idle' | 'loading' | 'done'>('idle');
  const [fallback, setFallback] = useState(false);
  const [tip, setTip] = useState('');
  useEffect(() => { setNow(new Date()); }, []);

  const txs = (app?.rows('transaction') || []) as R[];
  const budgets = (app?.rows('budget') || []) as R[];
  const loading = !now || (!!app?.loading('transaction') && txs.length === 0);
  const ym = now ? ymd(now).slice(0, 7) : '';

  const data = useMemo(() => {
    const months: { key: string; label: string; spent: number; income: number }[] = [];
    if (now) {
      for (let i = 2; i >= 0; i--) {
        const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
        months.push({ key: d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0'), label: MONTHS[d.getMonth()], spent: 0, income: 0 });
      }
    }
    const spend: Record<string, number> = {};
    for (const t of txs) {
      const m = months.find((x) => x.key === String(t.date).slice(0, 7));
      const a = Number(t.amount);
      if (!m) continue;
      if (a < 0) { m.spent -= a; if (m.key === ym) spend[String(t.category)] = (spend[String(t.category)] || 0) - a; } else m.income += a;
    }
    const cur = months[months.length - 1];
    const prev = months[months.length - 2];
    const list = Object.keys(spend).map((k) => { const lim = budgets.find((b) => String(b.category) === k); return { k, v: spend[k], lim: lim ? Number(lim.monthly_limit) : 0 }; }).sort((a, b) => b.v - a.v);
    const over = list.filter((x) => x.lim > 0 && x.v > x.lim);
    return { months, cur, prev, list, over };
  }, [txs, budgets, now, ym]);

  const maxSpent = Math.max(1, ...data.months.map((m) => m.spent));
  const spent = data.cur ? data.cur.spent : 0;
  const income = data.cur ? data.cur.income : 0;
  const prevSpent = data.prev ? data.prev.spent : 0;

  const localTake = (): string[] => {
    const top = data.list[0];
    const out: string[] = [];
    out.push('You have spent ' + money(spent, 0) + ' so far this month' + (top ? ', led by ' + cat(top.k).label.toLowerCase() + ' at ' + money(top.v, 0) + '.' : '.'));
    out.push(data.over.length ? data.over.map((o) => cat(o.k).label + ' is ' + money(o.v - o.lim, 0) + ' over its ' + money(o.lim, 0) + ' budget').join('; ') + '.' : 'Every category is still inside its budget — nice work.');
    out.push(income >= spent ? 'You are ' + money(income - spent, 0) + ' ahead of your spending, so there is room to move money into savings.' : 'Spending is ' + money(spent - income, 0) + ' above income this month, so ease off discretionary categories.');
    return out;
  };

  const explain = async () => {
    if (!app || state === 'loading') return;
    setState('loading');
    setBullets([]);
    const summary = {
      month: ym,
      spent_so_far: Math.round(spent),
      income_so_far: Math.round(income),
      last_month_spent: Math.round(prevSpent),
      categories: data.list.map((x) => ({ category: x.k, spent: Math.round(x.v), budget: x.lim || null })),
    };
    let out: string[] = [];
    let fb = false;
    try {
      const text = await app.ai.ask('Explain my month. Here is my data as JSON: ' + JSON.stringify(summary), { system: 'You are Ledgerly, a friendly personal finance coach. Summarise the member spending versus their budgets in exactly 3 bullet points, then one last line that starts with Tip: and gives one practical tip. Each bullet starts with a dash and a space, is at most 28 words, uses real dollar figures from the data, and is plain text with no markdown formatting, no headings and no intro.', maxTokens: 380 });
      out = text.split('\n').map((l) => l.replace(/^[\s\-•*]+/, '').replace(/\*\*/g, '').trim()).filter((l) => l.length > 8); const tl = out.find((l) => /^tip:/i.test(l)); setTip(tl ? tl.replace(/^tip:\s*/i, '') : ''); out = out.filter((l) => !/^tip:/i.test(l)).slice(0, 3);
    } catch (e) { out = []; }
    if (out.length < 3) { out = localTake(); fb = true; setTip(''); }
    setFallback(fb);
    setBullets(out);
    setState('done');
  };

  const icons = [TrendingDown, Target, Sparkles];
  const tints = ['#2F6BFF', '#EF4444', '#10B981'];

  return (
    <Shell app={app} active='insights'>
      <Rise>
        <div className='mb-6'>
          <div className='text-sm font-medium text-slate-400'>Understand your money</div>
          <div className='text-3xl font-semibold tracking-tight lg:text-4xl'>Insights</div>
        </div>
      </Rise>

      {loading ? (
        <div className='space-y-4'><div className='h-56 animate-pulse rounded-3xl bg-slate-200/70' /><div className='h-64 animate-pulse rounded-3xl bg-slate-200/70' /></div>
      ) : (
        <div className='grid grid-cols-[minmax(0,1fr)] gap-5 lg:grid-cols-5'>
          <Rise i={1} className='lg:col-span-3'>
            <div className='relative overflow-hidden rounded-[32px] bg-gradient-to-br from-[#0F1F4D] via-[#14308A] to-primary p-6 text-white shadow-[0_24px_50px_-18px_rgba(20,48,138,0.8)] lg:p-8'>
              <div className='pointer-events-none absolute -right-10 -top-16 h-56 w-56 rounded-full bg-primary/40 blur-3xl' />
              <div className='relative flex items-center gap-2 text-sm font-semibold text-white/80'><Sparkles size={16} /> Explain my month</div>
              <div className='relative mt-2 text-2xl font-semibold leading-tight tracking-tight lg:text-3xl'>Three bullets on how this month is going.</div>

              <div className='relative mt-5 space-y-3'>
                {state === 'loading' && [0, 1, 2].map((i) => <motion.div key={i} animate={{ opacity: [0.35, 0.8, 0.35] }} transition={{ duration: 1.4, repeat: Infinity, delay: i * 0.2 }} className='h-[60px] rounded-2xl bg-white/15' />)}
                <AnimatePresence>
                  {state === 'done' && bullets.map((b, i) => {
                    const I = icons[i % 3];
                    return (
                      <motion.div key={i} initial={reduce ? false : { opacity: 0, y: 14, scale: 0.98 }} animate={{ opacity: 1, y: 0, scale: 1 }} transition={{ delay: i * 0.18, type: 'spring', stiffness: 200, damping: 22 }} className='flex gap-3 rounded-2xl bg-white p-4 text-slate-800 shadow-lg'>
                        <div className='flex h-9 w-9 shrink-0 items-center justify-center rounded-xl' style={{ background: tints[i % 3] + '1A', color: tints[i % 3] }}><I size={18} /></div>
                        <div className='text-[15px] leading-snug'>{b}</div>
                      </motion.div>
                    );
                  })}
                </AnimatePresence>
                {state === 'done' && tip && <motion.div initial={reduce ? false : { opacity: 0, y: 14 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.6 }} className='flex gap-3 rounded-2xl bg-white/15 p-4 text-white ring-1 ring-white/25'><div className='flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-white/20'><Sparkles size={18} /></div><div className='text-[15px] leading-snug'><span className='font-semibold'>Tip: </span>{tip}</div></motion.div>}
                {state === 'idle' && <div className='rounded-2xl bg-white/10 px-4 py-5 text-sm text-white/75'>Tap the button and Ledgerly will compare your spending with your budgets.</div>}
              </div>

              <motion.button whileTap={{ scale: 0.96 }} whileHover={{ y: -1 }} onClick={explain} disabled={state === 'loading'} className='relative mt-5 flex items-center gap-2 rounded-2xl bg-white px-5 py-3.5 text-sm font-semibold text-primary shadow-lg disabled:opacity-70'>
                {state === 'loading' ? <motion.span animate={{ rotate: 360 }} transition={{ duration: 1, repeat: Infinity, ease: 'linear' }} className='flex'><RefreshCw size={16} /></motion.span> : <Sparkles size={16} />}
                {state === 'loading' ? 'Reading your month' : state === 'done' ? 'Explain again' : 'Explain my month'}
              </motion.button>
              {state === 'done' && fallback && <div className='relative mt-3 text-xs text-white/60'>AI is resting right now, try again soon. Here is a quick take in the meantime.</div>}
            </div>
          </Rise>

          <Rise i={2} className='lg:col-span-2'>
            <div className='grid h-full grid-cols-2 gap-4 lg:grid-cols-1'>
              <div className={CARD}><div className='flex items-center gap-1.5 text-xs font-medium text-slate-400'><TrendingDown size={14} /> Spent this month</div><div className='mt-1 text-3xl font-semibold tabular-nums'>{money(spent, 0)}</div><div className={'mt-1 text-xs font-medium ' + (spent > prevSpent ? 'text-red-500' : 'text-emerald-600')}>{prevSpent ? (spent > prevSpent ? 'Up ' : 'Down ') + money(Math.abs(spent - prevSpent), 0) + ' vs last month' : 'First month tracked'}</div></div>
              <div className={CARD}><div className='flex items-center gap-1.5 text-xs font-medium text-slate-400'><TrendingUp size={14} /> Income</div><div className='mt-1 text-3xl font-semibold tabular-nums text-emerald-600'>{money(income, 0)}</div><div className='mt-1 text-xs text-slate-400'>{data.over.length ? data.over.length + (data.over.length === 1 ? ' category over budget' : ' categories over budget') : 'All budgets on track'}</div></div>
            </div>
          </Rise>

          <Rise i={3} className='lg:col-span-3'>
            <div className={CARD}>
              <div className='mb-1 text-lg font-semibold'>Spending trend</div>
              <div className='mb-4 text-xs text-slate-400'>Last three months</div>
              <div className='flex h-48 items-end gap-4'>
                {data.months.map((m, i) => {
                  const cur = i === data.months.length - 1;
                  return (
                    <div key={m.key} className='flex h-full flex-1 flex-col items-center justify-end gap-2'>
                      <div className='text-xs font-semibold tabular-nums text-slate-500'>{money(m.spent, 0)}</div>
                      <motion.div className='w-full rounded-2xl' style={{ background: cur ? 'hsl(var(--primary))' : '#D5DEF5', originY: 1 }} initial={reduce ? false : { height: 0 }} animate={{ height: Math.max((m.spent / maxSpent) * 100, 3) + '%' }} transition={{ duration: 0.9, delay: 0.2 + i * 0.1, ease: [0.22, 1, 0.36, 1] }} />
                      <div className={'text-xs font-medium ' + (cur ? 'text-primary' : 'text-slate-400')}>{m.label}</div>
                    </div>
                  );
                })}
              </div>
            </div>
          </Rise>

          <Rise i={4} className='lg:col-span-2'>
            <div className={CARD + ' h-full'}>
              <div className='mb-4 text-lg font-semibold'>Where it went</div>
              <div className='space-y-4'>
                {data.list.slice(0, 6).map((s, i) => {
                  const c = cat(s.k);
                  const over = s.lim > 0 && s.v > s.lim;
                  return (
                    <div key={s.k}>
                      <div className='mb-1 flex items-center justify-between text-sm'><span className='flex items-center gap-2 font-medium'><c.Icon size={15} style={{ color: c.color }} /> {c.label}</span><span className={'tabular-nums ' + (over ? 'font-semibold text-red-500' : 'text-slate-500')}>{money(s.v, 0)}</span></div>
                      <div className='h-2 overflow-hidden rounded-full bg-slate-100'><motion.div className='h-full rounded-full' style={{ background: over ? '#EF4444' : c.color }} initial={reduce ? false : { width: 0 }} animate={{ width: (data.list[0] ? (s.v / data.list[0].v) * 100 : 0) + '%' }} transition={{ duration: 0.8, delay: 0.3 + i * 0.07 }} /></div>
                    </div>
                  );
                })}
                {data.list.length === 0 && <div className='py-6 text-center text-sm text-slate-400'>No spending recorded this month yet.</div>}
              </div>
            </div>
          </Rise>
        </div>
      )}
    </Shell>
  );
}

