  const [v, setV] = useState(reduce ? TARGET : 0);
  useEffect(() => {
    if (reduce) { setV(TARGET); return; }
    const c = animate(0, TARGET, { duration: 1.6, delay: 0.3, ease: [0.22, 1, 0.36, 1], onUpdate: (x) => setV(x) });
    return () => c.stop();
  }, [reduce]);
  return (
    <div className='relative overflow-hidden rounded-2xl bg-slate-50 p-4 ring-1 ring-slate-200/70'>
      <div className='flex items-start justify-between gap-3'>
        <div className='min-w-0'>
          <div className='text-xs font-medium text-slate-400'>Total balance</div>
          <div className='mt-0.5 text-[28px] font-semibold leading-none tracking-tight tabular-nums text-slate-900'>{money(v)}</div>
          <div className='mt-2 inline-flex items-center gap-1 rounded-full bg-emerald-50 px-2 py-0.5 text-[11px] font-semibold text-emerald-600'><TrendingUp size={12} /> +$1,284 this month</div>
        </div>
        <svg viewBox={'0 0 ' + W + ' ' + H} className='mt-1 h-14 w-[42%] max-w-[150px] shrink-0 overflow-visible' aria-hidden='true'>
          <defs>
            <linearGradient id='lg-spark' x1='0' y1='0' x2='0' y2='1'>
              <stop offset='0%' stopColor='hsl(var(--primary))' stopOpacity='0.25' />
              <stop offset='100%' stopColor='hsl(var(--primary))' stopOpacity='0' />
            </linearGradient>
          </defs>
          <motion.path d={AREA} fill='url(#lg-spark)' initial={reduce ? false : { opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 1.1, duration: 0.8 }} />
          <motion.path d={LINE} fill='none' stroke='hsl(var(--primary))' strokeWidth='2.5' strokeLinecap='round' strokeLinejoin='round' initial={reduce ? false : { pathLength: 0 }} animate={{ pathLength: 1 }} transition={{ delay: 0.3, duration: 1.4, ease: 'easeInOut' }} />
          <motion.circle cx={xy[xy.length - 1][0]} cy={xy[xy.length - 1][1]} r='4' fill='hsl(var(--primary))' initial={reduce ? false : { scale: 0 }} animate={{ scale: 1 }} transition={{ delay: 1.6, type: 'spring', stiffness: 300, damping: 15 }} />
        </svg>
      </div>
    </div>
  );
}

export default function LedgerlyAuth({ app }: { app?: AppHandle }) {
  const auth = app?.auth;
  const reduce = useReducedMotion();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [err, setErr] = useState('');
  const [busy, setBusy] = useState(false);
  const signup = auth?.mode === 'signup';
  const providers = auth?.providers || [];

  const go = async () => {
    if (!auth || busy) return;
    setErr('');
    setBusy(true);
    try {
      if (signup) await auth.signUp({ name: name || email.split('@')[0], email, password });
      else await auth.signIn(email, password);
    } catch (e) {
      setErr(e instanceof Error ? e.message : 'Something went wrong');
    }
    setBusy(false);
  };
  const social = async (pname: string) => {
    if (!auth) return;
    setErr('');
    try { await auth.startProvider(pname); } catch (e) { setErr(e instanceof Error ? e.message : 'Could not start that sign-in'); }
  };
  const input = 'w-full rounded-2xl border border-slate-200 bg-slate-50 px-4 py-3.5 text-[15px] text-slate-900 outline-none transition focus:border-primary focus:bg-white focus:ring-4 focus:ring-primary/15';
  const lbl = 'mb-1.5 block text-xs font-semibold uppercase tracking-wide text-slate-500';
  const grid = 'linear-gradient(rgba(255,255,255,0.09) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.09) 1px, transparent 1px)';

  return (
    <div className='relative min-h-screen overflow-x-hidden bg-primary'>
      <div className='pointer-events-none absolute inset-0' style={{ backgroundImage: grid, backgroundSize: '44px 44px', WebkitMaskImage: 'radial-gradient(ellipse at 50% 35%, #000 20%, transparent 75%)', maskImage: 'radial-gradient(ellipse at 50% 35%, #000 20%, transparent 75%)' }} />
      <div className='pointer-events-none absolute -left-24 -top-24 h-96 w-96 rounded-full bg-white/20 blur-3xl' />
      <div className='pointer-events-none absolute -bottom-32 -right-20 h-96 w-96 rounded-full bg-black/25 blur-3xl' />

      <div className='relative mx-auto flex min-h-screen w-full max-w-md flex-col items-center justify-center px-4 py-8'>
        <motion.div initial={reduce ? false : { opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} className='mb-5 flex items-center gap-2.5 text-white'>
          <div className='flex h-10 w-10 items-center justify-center rounded-xl bg-white text-lg font-bold text-primary shadow-lg'>L</div>
          <span className='text-xl font-semibold tracking-tight'>Ledgerly</span>
        </motion.div>

        <motion.div initial={reduce ? false : { opacity: 0, y: 28, scale: 0.98 }} animate={{ opacity: 1, y: 0, scale: 1 }} transition={{ type: 'spring', stiffness: 150, damping: 20 }} className='w-full rounded-[28px] bg-white p-5 shadow-[0_30px_70px_-20px_rgba(10,25,90,0.55),0_2px_6px_rgba(15,23,42,0.08)] sm:p-7'>
          <Preview reduce={reduce} />
          <div className='mt-5 text-2xl font-semibold tracking-tight text-slate-900'>{signup ? 'Create your account' : 'Welcome back'}</div>
          <p className='mt-1 text-sm text-slate-500'>{signup ? 'Start tracking in under a minute.' : 'Sign in to see where your money went.'}</p>

          <div className='mt-5 space-y-3.5'>
            <AnimatePresence initial={false}>
              {signup && (
                <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className='overflow-hidden'>
                  <label className={lbl} htmlFor='lg-name'>Name</label>
                  <input id='lg-name' className={input} value={name} onChange={(e) => setName(e.target.value)} placeholder='Your name' />
                </motion.div>
              )}
            </AnimatePresence>
            <div>
              <label className={lbl} htmlFor='lg-email'>Email</label>
              <input id='lg-email' aria-label='Email' type='email' autoComplete='email' className={input} value={email} onChange={(e) => setEmail(e.target.value)} placeholder='you@example.com' />
            </div>
            <div>
              <label className={lbl} htmlFor='lg-pass'>Password</label>
              <input id='lg-pass' aria-label='Password' type='password' autoComplete={signup ? 'new-password' : 'current-password'} className={input} value={password} onChange={(e) => setPassword(e.target.value)} placeholder='Your password' onKeyDown={(e) => { if (e.key === 'Enter') go(); }} />
            </div>
          </div>

          <AnimatePresence>
            {err && <motion.div role='alert' initial={{ opacity: 0, y: -6 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} className='mt-4 rounded-xl bg-red-50 px-4 py-2.5 text-sm text-red-600'>{err}</motion.div>}
          </AnimatePresence>

          <motion.button whileTap={{ scale: 0.97 }} whileHover={{ y: -1 }} onClick={go} disabled={busy} className='mt-5 flex w-full items-center justify-center gap-2 rounded-2xl bg-primary py-4 text-[15px] font-semibold text-primary-foreground shadow-[0_10px_24px_-8px_rgba(47,107,255,0.7)] disabled:opacity-60'>
            {busy ? 'Please wait' : signup ? 'Create account' : 'Sign in'}
          </motion.button>

          {providers.length > 0 && (
            <div className='mt-5'>
              <div className='mb-4 flex items-center gap-3 text-xs font-medium uppercase tracking-wide text-slate-400'>
                <span className='h-px flex-1 bg-slate-200' />or<span className='h-px flex-1 bg-slate-200' />
              </div>
              <div className='space-y-2.5'>
                {providers.map((p) => (
                  <motion.button key={p.name} whileTap={{ scale: 0.97 }} whileHover={{ y: -1 }} onClick={() => social(p.name)} className='flex w-full items-center justify-center gap-3 rounded-2xl border border-slate-200 bg-white py-3.5 text-[15px] font-semibold text-slate-800 shadow-sm hover:border-slate-300'>
                    {p.name === 'google' && <GoogleMark />}
                    Continue with {p.label}
                  </motion.button>
                ))}
              </div>
            </div>
          )}

          {auth?.canSignUp !== false && (
            <button className='mt-4 w-full text-center text-sm text-slate-500' onClick={() => { setErr(''); auth?.setMode(signup ? 'login' : 'signup'); }}>
              {signup ? 'Already have an account? ' : 'New to Ledgerly? '}
              <span className='font-semibold text-primary'>{signup ? 'Sign in' : 'Create an account'}</span>
            </button>
          )}

          {!signup && (
            <div className='mt-5 border-t border-slate-100 pt-4'>
              <div className='mb-2 text-xs font-semibold uppercase tracking-wide text-slate-400'>Try a demo member</div>
              <div className='grid grid-cols-2 gap-3'>
                {DEMOS.map((d) => (
                  <motion.button key={d.email} whileTap={{ scale: 0.96 }} onClick={() => { setEmail(d.email); setPassword(d.password); setErr(''); }} className='flex items-center gap-2.5 rounded-2xl border border-slate-200 bg-white px-3 py-2.5 text-left text-sm font-medium text-slate-800 hover:border-primary/40'>
                    <span className='flex h-8 w-8 items-center justify-center rounded-full bg-primary/10 text-xs font-bold text-primary'>{d.name[0]}</span>
                    <span className='flex-1'>{d.name}</span>
                    {email === d.email && <Check size={14} className='text-primary' />}
                  </motion.button>
                ))}
              </div>
            </div>
          )}
        </motion.div>
      </div>
    </div>
  );
}

